content.content:
1	package nettrace
2	
3	import (
4		"fmt"
5		"go/ast"
6		"go/parser"
7		"go/token"
8		"os"
9		"strconv"
10		"strings"
11		"testing"
12	)
13	
14	// The trace sends its probes itself, over ICMP and UDP sockets. It must never
15	// start a child process (traceroute, ping) nor replace the process image, on
16	// any platform. The guard reads every .go file of the package whatever its
17	// build constraints (go/parser does not evaluate them), so a file that only
18	// builds on another OS is covered too.
19	
20	// bannedImports are packages that must not be imported at all.
21	var bannedImports = map[string]bool{
22		"os/exec":                  true,
23		"golang.org/x/sys/execabs": true,
24		// Windows services can launch processes.
25		"golang.org/x/sys/windows/svc":     true,
26		"golang.org/x/sys/windows/svc/mgr": true,
27	}
28	
29	// dotWatched are packages that must not be dot-imported: a dot-import hides
30	// the package name the selector check relies on.
31	var dotWatched = map[string]bool{
32		"os":                    true,
33		"syscall":               true,
34		"os/exec":               true,
35		"golang.org/x/sys/unix": true,
36		winPath:                 true,
37	}
38	
39	// winPath is the Windows system-call package. The Windows engine may use it
40	// to load iphlpapi.dll only (see the rules in guardSource).
41	const winPath = "golang.org/x/sys/windows"
42	
43	// winDLL is the one DLL the Windows engine may load.
44	const winDLL = "iphlpapi.dll"
45	
46	// winProcs is the exact, case-sensitive list of entry points NewProc may
47	// resolve: the IP Helper ICMP echo API, nothing else.
48	var winProcs = map[string]bool{
49		"IcmpCreateFile": true, "Icmp6CreateFile": true,
50		"IcmpSendEcho2": true, "Icmp6SendEcho2": true,
51		"IcmpCloseHandle": true,
52	}
53	
54	// bannedSymbols maps an import path to the process-launching symbols it must
55	// not expose here, called or not (`f := os.StartProcess` is caught too). The
56	// socket symbols the engine needs (Recvmsg, Setsockopt...) stay allowed.
57	var bannedSymbols = map[string]map[string]bool{
58		"os": {"StartProcess": true},
59		"syscall": {
60			"StartProcess": true, "ForkExec": true, "Exec": true,
61			"Syscall": true, "Syscall6": true, "RawSyscall": true, "RawSyscall6": true,
62			"SyscallN": true, "Syscall9": true, "Syscall12": true, "Syscall15": true, "Syscall18": true,
63			"CreateProcess": true, "CreateProcessAsUser": true,
64			"LoadLibrary": true, "GetProcAddress": true,
65			"LoadDLL": true, "MustLoadDLL": true, "NewLazyDLL": true,
66			"LazyDLL": true, "DLL": true, "LazyProc": true, "Proc": true,
67		},
68		"golang.org/x/sys/unix": {
69			"Exec":    true,
70			"Syscall": true, "Syscall6": true, "RawSyscall": true, "RawSyscall6": true,
71		},
72		winPath: {
73			"CreateProcess": true, "CreateProcessAsUser": true, "ShellExecute": true,
74			"Syscall": true, "Syscall6": true, "Syscall9": true, "Syscall12": true,
75			"Syscall15": true, "Syscall18": true, "SyscallN": true,
76			"LoadLibrary": true, "LoadLibraryEx": true,
77			"GetProcAddress": true, "GetProcAddressByOrdinal": true,
78			"LoadDLL": true, "MustLoadDLL": true, "NewLazyDLL": true,
79			// Naming these types would build a DLL handle without NewLazySystemDLL;
80			// NewProc and Call on the value NewLazySystemDLL returns need no name.
81			"LazyDLL": true, "DLL": true, "LazyProc": true, "Proc": true,
82			// Services start executables.
83			"CreateService": true, "StartService": true, "OpenSCManager": true,
84		},
85	}
86	
87	// isStringLit reports whether e is a string literal and returns its value.
88	func isStringLit(e ast.Expr) (string, bool) {
89		lit, ok := e.(*ast.BasicLit)
90		if !ok || lit.Kind != token.STRING {
91			return "", false
92		}
93		v, err := strconv.Unquote(lit.Value)
94		return v, err == nil
95	}
96	
97	// winCallOffence checks the two Windows loading rules on a call in a file
98	// that imports x/sys/windows: NewLazySystemDLL takes the literal "iphlpapi.dll"
99	// only, and NewProc takes a literal from winProcs only. It returns a message
100	// or "". One call is one offence at most.
101	func winCallOffence(fset *token.FileSet, call *ast.CallExpr, winNames map[string]bool) string {
102		sel, ok := call.Fun.(*ast.SelectorExpr)
103		if !ok || len(call.Args) != 1 {
104			return ""
105		}
106		lit, isLit := isStringLit(call.Args[0])
107		switch sel.Sel.Name {
108		case "NewLazySystemDLL":
109			id, ok := sel.X.(*ast.Ident)
110			if !ok || !winNames[id.Name] {
111				return ""
112			}
113			if !isLit || lit != winDLL {
114				return fmt.Sprintf("%s: NewLazySystemDLL may load only the literal %q", fset.Position(call.Pos()), winDLL)
115			}
116		case "NewProc":
117			if !isLit || !winProcs[lit] {
118				return fmt.Sprintf("%s: NewProc may resolve only the ICMP echo entry points by literal name", fset.Position(call.Pos()))
119			}
120		}
121		return ""
122	}
123	
124	// guardSource returns one message per offence in src ("name:line: ...").
125	func guardSource(fset *token.FileSet, name string, src any) ([]string, error) {
126		file, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
127		if err != nil {
128			return nil, err
129		}
130		var out []string
131		local := map[string]string{}  // local package name -> import path
132		winNames := map[string]bool{} // local names of x/sys/windows
133		importsSys := false           // syscall or x/sys/windows: the NewProc rules apply
134		for _, imp := range file.Imports {
135			path, _ := strconv.Unquote(imp.Path.Value)
136			if bannedImports[path] {
137				out = append(out, fmt.Sprintf("%s: import of %s", fset.Position(imp.Pos()), path))
138			}
139			if imp.Name != nil && imp.Name.Name == "." && dotWatched[path] {
140				out = append(out, fmt.Sprintf("%s: dot-import of %s", fset.Position(imp.Pos()), path))
141			}
142			if path == winPath || path == "syscall" {
143				importsSys = true
144			}
145			if _, watched := bannedSymbols[path]; !watched {
146				continue
147			}
148			n := path[strings.LastIndex(path, "/")+1:]
149			if imp.Name != nil {
150				n = imp.Name.Name
151			}
152			local[n] = path
153			if path == winPath {
154				winNames[n] = true
155			}
156		}
157		// calledLoad holds the bare windows.NewLazySystemDLL selectors that are the
158		// function of a call; any other reference (value, parentheses) is refused.
159		// calledProc does the same for the NewProc selectors.
160		calledLoad := map[*ast.SelectorExpr]bool{}
161		calledProc := map[*ast.SelectorExpr]bool{}
162		ast.Inspect(file, func(n ast.Node) bool {
163			if call, ok := n.(*ast.CallExpr); ok && importsSys {
164				if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
165					switch sel.Sel.Name {
166					case "NewLazySystemDLL":
167						calledLoad[sel] = true
168					case "NewProc":
169						calledProc[sel] = true
170					}
171				}
172				if msg := winCallOffence(fset, call, winNames); msg != "" {
173					out = append(out, msg)
174				}
175				return true
176			}
177			sel, ok := n.(*ast.SelectorExpr)
178			if !ok {
179				return true
180			}
181			if importsSys && sel.Sel.Name == "NewProc" && !calledProc[sel] {
182				out = append(out, fmt.Sprintf("%s: NewProc must be called directly, not used as a value", fset.Position(sel.Pos())))
183			}
184			id, ok := sel.X.(*ast.Ident)
185			if !ok {
186				return true
187			}
188			if winNames[id.Name] && sel.Sel.Name == "NewLazySystemDLL" && !calledLoad[sel] {
189				out = append(out, fmt.Sprintf("%s: %s.NewLazySystemDLL must be called directly, not used as a value", fset.Position(sel.Pos()), id.Name))
190			}
191			if path, ok := local[id.Name]; ok && bannedSymbols[path][sel.Sel.Name] {
192				out = append(out, fmt.Sprintf("%s: use of %s.%s", fset.Position(sel.Pos()), id.Name, sel.Sel.Name))
193			}
194			return true
195		})
196		return out, nil
197	}
198	
199	func TestGuardSourceFlagsOffences(t *testing.T) {
200		for _, c := range []struct {
201			name, src string
202			want      int
203		}{
204			{"exec.go", "package x\nimport \"os/exec\"\nfunc f() { _ = exec.Command(\"traceroute\") }\n", 1},
205			{"aliased_exec.go", "package x\nimport e \"os/exec\"\nvar _ = e.Command\n", 1},
206			{"startprocess.go", "package x\nimport \"os\"\nfunc f() { _, _ = os.StartProcess(\"a\", nil, nil) }\n", 1},
207			{"forkexec.go", "package x\nimport \"syscall\"\nfunc f() { _, _ = syscall.ForkExec(\"a\", nil, nil); _ = syscall.Exec(\"a\", nil, nil) }\n", 2},
208			{"unix.go", "package x\nimport \"golang.org/x/sys/unix\"\nfunc f() { _ = unix.Exec(\"a\", nil, nil) }\n", 1},
209			{"aliased_unix.go", "package x\nimport u \"golang.org/x/sys/unix\"\nfunc f() { _ = u.Exec(\"a\", nil, nil) }\n", 1},
210			{"tagged.go", "//go:build windows\n\npackage x\nimport \"os/exec\"\nvar _ = exec.Command\n", 1},
211			{"execabs.go", "package x\nimport \"golang.org/x/sys/execabs\"\nvar _ = execabs.Command\n", 1},
212			{"syscall_startprocess.go", "package x\nimport \"syscall\"\nfunc f() { _, _ = syscall.StartProcess(\"a\", nil, nil) }\n", 1},
213			{"raw_syscall.go", "package x\nimport \"syscall\"\nfunc f() { syscall.RawSyscall(59, 0, 0); syscall.Syscall(59, 0, 0, 0); syscall.Syscall6(59, 0, 0, 0, 0, 0, 0); syscall.RawSyscall6(59, 0, 0, 0, 0, 0, 0) }\n", 4},
214			{"unix_syscall.go", "package x\nimport \"golang.org/x/sys/unix\"\nfunc f() { unix.Syscall(59, 0, 0, 0); unix.RawSyscall6(59, 0, 0, 0, 0, 0, 0) }\n", 2},
215			{"func_value.go", "package x\nimport \"os\"\nvar f = os.StartProcess\n", 1},
216			{"dot_os.go", "package x\nimport . \"os\"\nvar _ = Getpid\n", 1},
217			{"dot_syscall.go", "package x\nimport . \"syscall\"\nvar _ = Getpid\n", 1},
218			{"dot_exec.go", "package x\nimport . \"os/exec\"\nvar _ = Command\n", 2},
219			{"dot_unix.go", "package x\nimport . \"golang.org/x/sys/unix\"\nvar _ = Getpid\n", 1},
220			{"allowed_unix.go", "package x\nimport \"golang.org/x/sys/unix\"\nfunc f() { _ = unix.Setsockopt; _ = unix.Recvmsg }\n", 0},
221			// DEVDESK-488: the Windows engine may load iphlpapi.dll only, through
222			// x/sys/windows, and call five named ICMP entry points.
223			{"win_createprocess.go", "package x\nimport \"golang.org/x/sys/windows\"\nfunc f() { _ = windows.CreateProcess }\n", 1},
224			{"win_createprocess_aliased.go", "package x\nimport w \"golang.org/x/sys/windows\"\nfunc f() { _ = w.CreateProcessAsUser }\n", 1},
225			{"win_banned_symbols.go", "package x\nimport \"golang.org/x/sys/windows\"\nfunc f() { _ = windows.ShellExecute; _ = windows.Syscall; _ = windows.Syscall6; _ = windows.Syscall9; _ = windows.Syscall12; _ = windows.Syscall15; _ = windows.Syscall18; _ = windows.SyscallN; _ = windows.LoadLibrary; _ = windows.LoadLibraryEx; _ = windows.GetProcAddress; _ = windows.GetProcAddressByOrdinal; _ = windows.LoadDLL; _ = windows.MustLoadDLL; _ = windows.NewLazyDLL }\n", 15},
226			{"win_dot.go", "package x\nimport . \"golang.org/x/sys/windows\"\nvar _ = GetCurrentProcessId\n", 1},
227			{"win_lazy_system_ok.go", "package x\nimport \"golang.org/x/sys/windows\"\nvar dll = windows.NewLazySystemDLL(\"iphlpapi.dll\")\n", 0},
228			{"win_lazy_system_other.go", "package x\nimport \"golang.org/x/sys/windows\"\nvar dll = windows.NewLazySystemDLL(\"kernel32.dll\")\n", 1},
229			{"win_lazy_system_var.go", "package x\nimport \"golang.org/x/sys/windows\"\nfunc f(n string) { _ = windows.NewLazySystemDLL(n) }\n", 1},
230			{"win_newproc_bad.go", "package x\nimport \"golang.org/x/sys/windows\"\nvar p = windows.NewLazySystemDLL(\"iphlpapi.dll\").NewProc(\"CreateProcessW\")\n", 1},
231			{"win_newproc_var.go", "package x\nimport \"golang.org/x/sys/windows\"\nfunc f(name string) { _ = windows.NewLazySystemDLL(\"iphlpapi.dll\").NewProc(name) }\n", 1},
232			{"win_newproc_ok.go", "package x\nimport \"golang.org/x/sys/windows\"\nvar p = windows.NewLazySystemDLL(\"iphlpapi.dll\").NewProc(\"IcmpSendEcho2\")\n", 0},
233			{"win_newproc_allowlist.go", "package x\nimport \"golang.org/x/sys/windows\"\nvar d = windows.NewLazySystemDLL(\"iphlpapi.dll\")\nvar a, b, c, e, g = d.NewProc(\"IcmpCreateFile\"), d.NewProc(\"Icmp6CreateFile\"), d.NewProc(\"IcmpSendEcho2\"), d.NewProc(\"Icmp6SendEcho2\"), d.NewProc(\"IcmpCloseHandle\")\n", 0},
234			{"win_newproc_case.go", "package x\nimport \"golang.org/x/sys/windows\"\nvar p = windows.NewLazySystemDLL(\"iphlpapi.dll\").NewProc(\"icmpsendecho2\")\n", 1},
235			// Review round 1: NewLazySystemDLL may only be the called function itself.
236			{"win_load_value.go", "package x\nimport \"golang.org/x/sys/windows\"\nvar load = windows.NewLazySystemDLL\nvar d = load(\"kernel32.dll\")\n", 1},
237			{"win_load_paren.go", "package x\nimport \"golang.org/x/sys/windows\"\nvar d = (windows.NewLazySystemDLL)(\"kernel32.dll\")\n", 1},
238			{"win_load_alias.go", "package x\nimport w \"golang.org/x/sys/windows\"\nvar load = w.NewLazySystemDLL\nvar d = w.NewLazySystemDLL(\"kernel32.dll\")\n", 2},
239			{"win_load_alias_ok.go", "package x\nimport w \"golang.org/x/sys/windows\"\nvar d = w.NewLazySystemDLL(\"iphlpapi.dll\")\n", 0},
240			{"win_lazydll_lit.go", "package x\nimport \"golang.org/x/sys/windows\"\nvar d = &windows.LazyDLL{Name: \"kernel32.dll\"}\nvar p = d.NewProc(\"IcmpSendEcho2\")\n", 1},
241			{"win_dll_types.go", "package x\nimport \"golang.org/x/sys/windows\"\nvar a *windows.DLL\nvar b *windows.LazyProc\nvar c *windows.Proc\n", 3},
242			{"win_svc_import.go", "package x\nimport _ \"golang.org/x/sys/windows/svc/mgr\"\n", 1},
243			// Review round 2: syscall's DLL types, NewProc used as a value, services.
244			{"syscall_dll_types.go", "package x\nimport \"syscall\"\nvar a *syscall.DLL\nvar b *syscall.LazyDLL\nvar c *syscall.LazyProc\nvar d *syscall.Proc\n", 4},
245			{"syscall_lazydll_call.go", "package x\nimport \"syscall\"\nfunc f() { (&syscall.LazyDLL{Name: \"kernel32.dll\"}).NewProc(\"CreateProcessW\").Call() }\n", 2},
246			{"win_newproc_value.go", "package x\nimport \"golang.org/x/sys/windows\"\nvar d = windows.NewLazySystemDLL(\"iphlpapi.dll\")\nvar f = d.NewProc\nvar p = f(\"CreateProcessW\")\n", 1},
247			{"win_newproc_paren.go", "package x\nimport \"golang.org/x/sys/windows\"\nvar d = windows.NewLazySystemDLL(\"iphlpapi.dll\")\nvar p = (d.NewProc)(\"CreateProcessW\")\n", 1},
248			{"win_newproc_paren_ok_name.go", "package x\nimport \"golang.org/x/sys/windows\"\nvar d = windows.NewLazySystemDLL(\"iphlpapi.dll\")\nvar p = (d.NewProc)(\"IcmpSendEcho2\")\n", 1},
249			{"syscall_newproc_value.go", "package x\nimport \"syscall\"\nfunc f(d interface{ NewProc(string) }) { g := d.NewProc; g(\"x\") }\n", 1},
250			{"win_services.go", "package x\nimport \"golang.org/x/sys/windows\"\nfunc f() { _ = windows.CreateService; _ = windows.StartService; _ = windows.OpenSCManager }\n", 3},
251			{"win_unrelated_newproc.go", "package x\ntype t struct{}\nfunc (t) NewProc(string) {}\nfunc f(n string) { t{}.NewProc(n) }\n", 0},
