1	//go:build linux
2	
3	package nettrace
4	
5	import (
6		"context"
7		"errors"
8		"fmt"
9		"net"
10		"net/netip"
11		"os"
12		"strconv"
13		"syscall"
14		"time"
15	
16		"golang.org/x/sys/unix"
17	)
18	
19	// defaultProbePort is the destination port of every probe, the traditional
20	// traceroute base port plus one: nothing normally listens there, so the target
21	// answers with Port Unreachable.
22	const defaultProbePort = 33435
23	
24	// probePayload is the neutral content of a probe.
25	var probePayload = []byte("abcdefghijklmnopqrstuvwabcdefghi")
26	
27	// errQueueBufLen sizes the control buffer for one IP_RECVERR message
28	// (cmsghdr, sock_extended_err and the offender's sockaddr).
29	const errQueueBufLen = 256
30	
31	var errNoExtendedErr = errors.New("no IP_RECVERR control message in the error queue")
32	
33	func supported() error { return nil }
34	
35	// systemProber returns the prober that uses the system's sockets.
36	func systemProber() prober { return linuxProber{} }
37	
38	// linuxProber probes with one connected, unprivileged UDP socket per TTL: the
39	// TTL is set with IP_TTL, IP_RECVERR makes the kernel queue the ICMP errors
40	// the probe provokes, and await reads them from the socket's error queue.
41	type linuxProber struct {
42		port int // destination port; 0 means defaultProbePort
43	}
44	
45	func (p linuxProber) open(ctx context.Context, dst netip.Addr, ttl int) (probeConn, error) {
46		port := p.port
47		if port == 0 {
48			port = defaultProbePort
49		}
50		d := net.Dialer{Control: func(_, _ string, c syscall.RawConn) error {
51			var serr error
52			if err := c.Control(func(fd uintptr) {
53				serr = unix.SetsockoptInt(int(fd), unix.IPPROTO_IP, unix.IP_TTL, ttl)
54				if serr == nil {
55					serr = unix.SetsockoptInt(int(fd), unix.IPPROTO_IP, unix.IP_RECVERR, 1)
56				}
57			}); err != nil {
58				return err
59			}
60			if serr != nil {
61				return os.NewSyscallError("setsockopt", serr)
62			}
63			return nil
64		}}
65		conn, err := d.DialContext(ctx, "udp4", net.JoinHostPort(dst.String(), strconv.Itoa(port)))
66		if err != nil {
67			var se *os.SyscallError
68			if errors.As(err, &se) && se.Syscall == "connect" {
69				return nil, connectError(err)
70			}
71			return nil, unsupportedSocketError(err)
72		}
73		udp := conn.(*net.UDPConn)
74		raw, err := udp.SyscallConn()
75		if err != nil {
76			_ = udp.Close()
77			return nil, err
78		}
79		return &linuxConn{conn: udp, raw: raw}, nil
80	}
81	
82	// unsupportedSocketError maps a socket or setsockopt failure that means "this
83	// system will not do unprivileged probing" to ErrUnsupported, keeping the raw
84	// error. Other errors (EMFILE...) are returned as they are.
85	func unsupportedSocketError(err error) error {
86		for _, errno := range []error{syscall.ENOPROTOOPT, syscall.EOPNOTSUPP, syscall.EPERM, syscall.EACCES} {
87			if errors.Is(err, errno) {
88				return fmt.Errorf("%w: %w", ErrUnsupported, err)
89			}
90		}
91		return err
92	}
93	
94	// linuxConn is single-use: one send, then one await.
95	type linuxConn struct {
96		conn *net.UDPConn
97		raw  syscall.RawConn
98	}
99	
100	func (c *linuxConn) send() (time.Time, error) {
101		sentAt := time.Now()
102		if _, err := c.conn.Write(probePayload); err != nil {
103			return time.Time{}, err
104		}
105		return sentAt, nil
106	}
107	
108	// await reads the socket's error queue until an error arrives, until passes
109	// (errSilent) or ctx ends (ctx.Err()).
110	func (c *linuxConn) await(ctx context.Context, until time.Time) (reply, error) {
111		if err := ctx.Err(); err != nil {
112			return reply{}, err
113		}
114		if err := c.conn.SetReadDeadline(until); err != nil {
115			return reply{}, err
116		}
117		// Registered after the deadline is set, so the callback's past deadline
118		// always wins. ctx.Err() tells a cancellation from a timeout afterwards.
119		stop := context.AfterFunc(ctx, func() { _ = c.conn.SetReadDeadline(time.Unix(1, 0)) })
120		defer stop()
121	
122		oob := make([]byte, errQueueBufLen)
123		var oobn int
124		var recvErr error
125		err := c.raw.Read(func(fd uintptr) bool {
126			buf := make([]byte, 1)
127			for {
128				_, oobn, _, _, recvErr = unix.Recvmsg(int(fd), buf, oob, unix.MSG_ERRQUEUE|unix.MSG_DONTWAIT)
129				if recvErr != unix.EINTR {
130					break
131				}
132			}
133			return recvErr != unix.EAGAIN
134		})
135		switch {
136		case ctx.Err() != nil && err != nil:
137			return reply{}, ctx.Err()
138		case errors.Is(err, os.ErrDeadlineExceeded):
139			// When ctx's own deadline is not after until, the trace's deadline
140			// (not the probe timeout) is what ran out: let ctx report it.
141			if dl, ok := ctx.Deadline(); ok && !dl.After(until) {
142				<-ctx.Done()
143				return reply{}, ctx.Err()
144			}
145			return reply{}, errSilent
146		case err != nil:
147			return reply{}, err
148		case recvErr != nil:
149			return reply{}, os.NewSyscallError("recvmsg", recvErr)
150		}
151		return parseErrQueue(oob[:oobn])
152	}
153	
154	func (c *linuxConn) close() error { return c.conn.Close() }
155	
156	// parseErrQueue decodes the IP_RECVERR control message of a MSG_ERRQUEUE read.
157	func parseErrQueue(oob []byte) (reply, error) {
158		msgs, err := unix.ParseSocketControlMessage(oob)
159		if err != nil {
160			return reply{}, err
161		}
162		for _, m := range msgs {
163			if m.Header.Level == unix.SOL_IP && m.Header.Type == unix.IP_RECVERR {
164				return decodeExtendedErr(m.Data)
165			}
166		}
167		return reply{}, errNoExtendedErr
168	}
