13	// prober opens one probe connection per TTL. The system implementation lives
14	// in the platform files; the tests drive run with a fake.
15	type prober interface {
16		// open returns a connection whose probes leave with the given TTL.
17		open(ctx context.Context, dst netip.Addr, ttl int) (probeConn, error)
18	}
19	
20	// probeConn sends one probe and waits for what answers it.
21	type probeConn interface {
22		// send emits the probe and returns the time it left.
23		send() (time.Time, error)
24		// await waits for the answer until the given time. It returns errSilent
25		// when nothing came back by then, and ctx.Err() when ctx ended first.
26		await(ctx context.Context, until time.Time) (reply, error)
27		close() error
28	}
29	
30	// errSilent is await's answer when nothing came back before its deadline.
31	var errSilent = errors.New("no answer before the probe timeout")
32	
33	// probeResult is what one TTL's goroutine hands back. resolved is false when
34	// the probe was cut short (cancellation, deadline, upper TTL no longer needed).
35	type probeResult struct {
36		ttl      int
37		hop      Hop
38		resolved bool
39	}
40	
41	// run traces the path with p. Every connection is opened first, in the
42	// caller's goroutine, so that a failing open stops everything before any
43	// probe is sent; then one goroutine per TTL sends and awaits in parallel.
44	//
45	// onHop, when not nil, is called once per resolved hop, one call at a time and
46	// always from the goroutine that called run, so it needs no lock. It is never
47	// called for an unresolved hop nor after run has returned. A hop above the
48	// terminal TTL may be reported while the terminal is still unknown; Result is
49	// cut at the terminal hop, so the caller reconciles with the final Result.
50	func run(ctx context.Context, target netip.Addr, opts Options, p prober, onHop func(Hop)) (Result, error) {
51		opts = opts.Normalized()
52		start := time.Now()
53		runCtx, cancel := context.WithTimeout(ctx, opts.Deadline)
54		defer cancel()
55	
56		conns, err := openAll(runCtx, p, target, opts.MaxHops)
57		if err != nil {
58			if runCtx.Err() != nil {
59				return endedEarly(runCtx, target, nil, opts.MaxHops, start), nil
60			}
61			return Result{}, openError(err)
62		}
63		return probeAll(runCtx, target, opts, conns, start, onHop), nil
64	}
65	
66	// openAll opens one connection per TTL, 1 to n. On failure it closes the ones
67	// already open and returns the error.
68	func openAll(ctx context.Context, p prober, target netip.Addr, n int) ([]probeConn, error) {
69		conns := make([]probeConn, 0, n)
70		for ttl := 1; ttl <= n; ttl++ {
71			if err := ctx.Err(); err != nil {
72				closeAll(conns)
73				return nil, err
74			}
75			c, err := p.open(ctx, target, ttl)
76			if err != nil {
77				closeAll(conns)
78				return nil, err
79			}
80			conns = append(conns, c)
81		}
82		return conns, nil
83	}
84	
85	func closeAll(conns []probeConn) {
86		for _, c := range conns {
87			_ = c.close()
88		}
89	}
90	
91	// openError turns a refused socket option (ENOPROTOOPT, EOPNOTSUPP) into
92	// ErrUnsupported, keeping the raw error for the message. Anything else is
93	// returned as is: a refused connect() is not "unsupported", and the system
94	// prober wraps its own socket and setsockopt permission errors itself.
95	func openError(err error) error {
96		for _, errno := range []error{syscall.ENOPROTOOPT, syscall.EOPNOTSUPP} {
97			if errors.Is(err, errno) {
98				return fmt.Errorf("%w: %w", ErrUnsupported, err)
99			}
100		}
101		return err
102	}
103	
104	// probeAll runs phase 2: one goroutine per connection.
105	func probeAll(ctx context.Context, target netip.Addr, opts Options, conns []probeConn, start time.Time, onHop func(Hop)) Result {
106		n := len(conns)
107		results := make(chan probeResult, n)
108		cancels := make([]context.CancelFunc, n+1) // indexed by TTL
109		var wg sync.WaitGroup
110		for i, c := range conns {
111			ttl := i + 1
112			var tctx context.Context
113			tctx, cancels[ttl] = context.WithCancel(ctx)
114			wg.Add(1)
115			go func() {
116				defer wg.Done()
117				defer func() { _ = c.close() }()
118				results <- probeOne(tctx, c, ttl, target, opts.ProbeTimeout)
119			}()
120		}
121	
122		t := newTally(n)
123		// collectOne records an answer and streams it when it is a hop worth
124		// showing: resolved, and not above the terminal TTL.
125		collectOne := func(r probeResult) {
126			t.add(r)
127			if onHop == nil || !r.resolved {
128				return
129			}
130			if term := t.terminal(); term > 0 && r.ttl > term {
131				return
132			}
133			onHop(r.hop)
134		}
135		cutAbove := func() {
136			if term := t.terminal(); term > 0 {
137				for ttl := term + 1; ttl <= n; ttl++ {
138					cancels[ttl]()
139				}
140			}
141		}
142	collect:
143		for !t.complete() {
144			select {
145			case r := <-results:
146				collectOne(r)
147				cutAbove()
148			case <-ctx.Done():
149				break collect
150			}
151		}
152		for _, cancel := range cancels[1:] {
153			cancel()
154		}
155		wg.Wait()
156		close(results)
157		for r := range results { // answers that landed while stopping
158			collectOne(r)
159		}
160	
161		if t.complete() {
162			return t.result(target, start)
163		}
164		return endedEarly(ctx, target, t, n, start)
165	}
166	
167	// probeOne sends the probe for one TTL and turns what comes back into a Hop.
168	func probeOne(ctx context.Context, c probeConn, ttl int, target netip.Addr, timeout time.Duration) probeResult {
169		sentAt, err := c.send()
170		if err != nil {
171			if ctx.Err() != nil {
172				return probeResult{ttl: ttl}
173			}
174			return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
175		}
176		rep, err := c.await(ctx, sentAt.Add(timeout))
177		recvAt := time.Now()
178		switch {
179		case err != nil && ctx.Err() != nil:
180			return probeResult{ttl: ttl}
181		case errors.Is(err, errSilent):
182			return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopSilent}, resolved: true}
183		case err != nil:
184			return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
185		}
186		rtt := rep.RTT
187		if rtt == 0 {
188			rtt = recvAt.Sub(sentAt)
189		}
190		hop := Hop{TTL: ttl, Kind: classify(rep, target), Addr: rep.Addr, RTT: rtt, ICMPType: rep.ICMPType, ICMPCode: rep.ICMPCode}
191		return probeResult{ttl: ttl, hop: hop, resolved: true}
192	}
193	
194	// tally collects the resolved hops of a run.
195	type tally struct {
196		hops []probeResult // indexed by TTL, index 0 unused
197	}
198	
199	func newTally(n int) *tally { return &tally{hops: make([]probeResult, n+1)} }
200	
201	func (t *tally) add(r probeResult) {
202		if r.resolved {
203			t.hops[r.ttl] = r
204		}
205	}
206	
207	// terminal returns the smallest TTL that reached or was refused, or 0.
208	func (t *tally) terminal() int {
209		for ttl := 1; ttl < len(t.hops); ttl++ {
210			if r := t.hops[ttl]; r.resolved && (r.hop.Kind == HopTarget || r.hop.Kind == HopUnreachable) {
211				return ttl
212			}
213		}
214		return 0
215	}
216	
217	// complete reports whether the trace can end: every TTL up to the terminal
218	// one (or every TTL when there is none) is resolved.
219	func (t *tally) complete() bool {
220		limit := len(t.hops) - 1
221		if term := t.terminal(); term > 0 {
222			limit = term
223		}
224		for ttl := 1; ttl <= limit; ttl++ {
225			if !t.hops[ttl].resolved {
226				return false
227			}
228		}
229		return true
230	}
231	
232	// result builds the Result of a complete tally.
233	func (t *tally) result(target netip.Addr, start time.Time) Result {
234		last, outcome := len(t.hops)-1, OutcomeMaxHops
235		if term := t.terminal(); term > 0 {
236			last = term
237			outcome = OutcomeReached
238			if t.hops[term].hop.Kind == HopUnreachable {
239				outcome = OutcomeUnreachable
240			}
241		}
242		hops := make([]Hop, 0, last)
243		for ttl := 1; ttl <= last; ttl++ {
244			hops = append(hops, t.hops[ttl].hop)
245		}
246		return Result{Target: target, Outcome: outcome, Hops: hops, Duration: time.Since(start)}
247	}
248	
249	// endedEarly builds the Result of a run that ctx cut short: one entry per TTL
250	// (n entries, index TTL-1), the resolved hops as they are and every other one
251	// as HopUnresolved with its TTL. t is nil when nothing was probed yet.
252	func endedEarly(ctx context.Context, target netip.Addr, t *tally, n int, start time.Time) Result {
253		res := Result{Target: target, Outcome: OutcomeCancelled, Hops: make([]Hop, 0, n), Duration: time.Since(start)}
254		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
255			res.Outcome = OutcomeDeadline
256		}
257		for ttl := 1; ttl <= n; ttl++ {
258			if t != nil && t.hops[ttl].resolved {
259				res.Hops = append(res.Hops, t.hops[ttl].hop)
260			} else {
261				res.Hops = append(res.Hops, Hop{TTL: ttl, Kind: HopUnresolved})
262			}
263		}
264		return res
265	}
